/// Returns 1.0 if i == j, else 0.0.
///
/// The problem statement uses `int`; in Rust we use `i64` as a clear signed integer type.
/// This function is total for all finite i64 values (including negatives).
pub fn diag_val(i: i64, j: i64) -> f64 {
    if i == j { 1.0 } else { 0.0 }
}

/// Constructs an n×n identity matrix of f64.
///
/// - Exactly n rows
/// - Each row has exactly n elements
/// - Diagonal entries are 1.0, others 0.0
pub fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut matrix: Vec<Vec<f64>> = Vec::with_capacity(n);

    for i in 0..n {
        let mut row = vec![0.0f64; n];
        row[i] = 1.0;
        matrix.push(row);
    }

    matrix
}

